<template><div v-if="preview" class="shade preview-shade"><section class="modal preview-modal" role="dialog" aria-modal="true" aria-label="文件预览" ref="panel" @keydown="trap"><header class="modal-top"><FileGlyph :item="preview.item" size="mini"/><h2 class="truncate">{{preview.item.name}}<span v-if="preview.version"> · v{{preview.version.versionNumber}}</span></h2><span class="sample-pill">{{preview.edit?'在线编辑':'只读预览'}}</span><button v-if="preview.edit&&ticket" class="btn small" :disabled="saving" @click="save">{{saving?'保存中…':'保存'}}</button><button v-if="preview.item.allowDownload" class="btn small" @click="download">下载</button><button class="icon-button" aria-label="关闭预览" @click="close"><Icon name="close"/></button></header><div class="preview-body" :class="{'office-body':kind==='office'}"><div v-if="loading" class="empty">正在加载…</div><div v-else-if="error" class="empty"><h3>暂时无法预览</h3><p>{{error}}</p><button class="btn" @click="load">重试</button></div><div v-if="kind==='office'&&!error" id="next-office-editor"/><img v-else-if="kind==='image'&&url" class="local-image" :src="url" :alt="preview.item.name"/><iframe v-else-if="kind==='pdf'&&url" class="pdf-viewer" :src="url" title="PDF 预览"/><pre v-else-if="kind==='text'&&!loading" class="user-text">{{text}}</pre><div v-else-if="!loading&&!error&&kind!=='office'" class="empty"><h3>此格式暂不支持在线预览</h3><p>可以根据下载权限获取原文件。</p></div></div><footer class="preview-bottom"><span>{{message|| (preview.edit?'修改由文档服务保存，请确认保存成功后关闭。':'文件内容来自云盘，权限由服务端核对。')}}</span><span>Esc 关闭</span></footer></section></div></template>
<script setup>
import {computed,ref,watch,nextTick,onUnmounted} from 'vue';import {ui,confirm,run,changed,refreshShell} from '../state';import * as api from '../api';import Icon from './Icon.vue';import FileGlyph from './FileGlyph.vue';
const panel=ref(null);
const preview=computed(()=>ui.preview),loading=ref(false),error=ref(''),kind=ref(''),url=ref(''),text=ref(''),ticket=ref(''),saving=ref(false),message=ref(''),dirty=ref(false);let editor=null,seq=0,poll=null,lastFocus=null;
function clean(){clearInterval(poll);poll=null;editor?.destroyEditor?.();editor=null;if(url.value)URL.revokeObjectURL(url.value);url.value='';}
async function script(src){if(window.DocsAPI)return;await new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.onload=resolve;el.onerror=()=>reject(new Error('文档服务脚本加载失败'));document.head.appendChild(el);});}
async function load(){const p=preview.value;if(!p)return;const n=++seq;clean();loading.value=true;error.value='';kind.value='';text.value='';ticket.value='';message.value='';dirty.value=false;
try{const endpoint='/api/drive/items/'+api.encode(p.item.id);const response=p.version?await api.get(endpoint+'/versions/'+api.encode(p.version.id)+'/preview'):p.edit?await api.getDriveItemEdit(p.item.id):await api.getDriveItemPreview(p.item.id);
if(n!==seq)return;if(response.supported===false&&!(!p.edit&&/\.(md|txt|csv|json)$/i.test(p.item.name)))throw new Error(response.unavailableMessage||'此格式暂不支持在线预览');
kind.value=response.kind;
if(response.kind==='office'){ticket.value=p.edit?response.editTicket:response.previewTicket;const config=await api.get('/api/onlyoffice/'+(p.edit?'edit-config':'view-config'),{[p.edit?'editTicket':'previewTicket']:ticket.value});await script(config.docserviceApi);if(n!==seq)return;
loading.value=false;await nextTick();const options=config.docEditorConfig;options.events={...(options.events||{}),onDocumentStateChange:e=>{dirty.value=Boolean(e.data);},onError:e=>{error.value=e.data?.errorDescription||'文档服务异常';}};
editor=new window.DocsAPI.DocEditor('next-office-editor',options);
if(p.edit)poll=setInterval(()=>void pollStatus(),3000);
}else{const blob=await api.blob(response.previewUrl||endpoint+'/content');if(n!==seq)return;
if(blob.type.includes('pdf'))kind.value='pdf';else if(blob.type.startsWith('image/'))kind.value='image';else if(blob.type.startsWith('text/')||/\.(md|txt|csv|json)$/i.test(p.item.name))kind.value='text';
if(kind.value==='text')text.value=await blob.text();else url.value=URL.createObjectURL(blob);}
await nextTick();panel.value?.querySelector('button')?.focus();
if(n===seq&&!p.version){await api.send('/api/drive/me/recent-opened/'+api.encode(p.item.id));void refreshShell();}
}catch(e){if(n===seq)error.value=e.message;}finally{if(n===seq)loading.value=false;}}
async function pollStatus(){try{const state=await api.getOnlyofficeSaveStatus(ticket.value);message.value=state.message||state.state||'';if(state.state==='saved'){dirty.value=false;saving.value=false;}if(state.state==='failed'){saving.value=false;error.value=state.message||'保存失败';}}catch(e){message.value=e.message;}}
async function save(){await run(async()=>{saving.value=true;try{await api.forceSaveDriveItem(ticket.value);await pollStatus();}finally{saving.value=false;}});}
function trap(e){if(e.key==='Escape'){e.stopPropagation();void close();}if(e.key!=='Tab')return;const list=[...panel.value.querySelectorAll('button:not(:disabled),iframe')].filter(el=>el.getClientRects().length);if(!list.length)return;if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus();}}
async function close(){if(preview.value?.edit&&dirty.value&&!await confirm('关闭编辑？','文档可能仍在保存，请确认已保存；是否关闭？'))return;seq++;clean();ui.preview=null;changed();lastFocus?.focus?.();}
async function download(){await run(async()=>{const p=preview.value;if(p.version){const b=await api.blob('/api/drive/items/'+p.item.id+'/versions/'+p.version.id+'/download');const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=p.version.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);}else await api.downloadDriveItem(p.item);});}
watch(()=>preview.value?.id,id=>{if(id){lastFocus=document.activeElement;void load();}else clean();});onUnmounted(()=>{seq++;clean();});
</script>
